-- Motorcycle Comparison API - Kawasaki technical specifications
-- Generated from zontes-scraper/kawasaki_motos.json (scraped 2026-08-28T19:38:54+00:00) by
-- tools/import-kawasaki-specs.mjs.
--
-- Sources, as recorded by the scraper:
--   motorcyclist: https://motorcyclist.com.br/ficha/kawasaki
--   motorcyclespecs: https://www.motorcyclespecs.co.za/bikes/Kawasaki.htm
--   totalmotorcycle: https://www.totalmotorcycle.com/
--   fipe: https://parallelum.com.br/fipe/api/v1/motos/marcas/85/modelos
--
-- Three sources rather than the two the earlier brand imports had: totalmotorcycle.com joins the
-- Brazilian and the global sheet here, and it is where the road-test timings, the gear ratios and
-- the firing orders below come from. Its price fields are deliberately not imported. It publishes
-- MSRP in three currencies for a model year, the catalogue already carries a reference price from
-- FIPE under its own key, and a second disagreeing price on the same row helps nobody choose a bike.
--
-- The file name follows the sibling pattern, and unlike BMW it can. Flyway runs repeatable
-- migrations in description order, and this import only gap-fills, so it has to run after the FIPE
-- seed that creates the rows it fills. "motorcycles kawasaki specs ..." sorts after "motorcycles
-- brazil fipe ..." because k > b, so the ordering here is earned rather than arranged.
--
-- The JSON "id" is the same base slug the FIPE seed derives, so rows join on motorcycles.slug rather
-- than on any fuzzy name match. All 200 scraped model-years already exist in the catalogue
-- (196 from the FIPE snapshot, 4 from R__dev_seed.sql), so against today's seeds this import creates
-- no motorcycles and only fills gaps. 194 of them carry something usable and are emitted;
-- the 6 that do not are listed at the foot of this header.
-- The insert path below still runs: whether a row is new is derived from the database at run time
-- rather than from a flag baked in here, so a slug the catalogue does not have is created rather
-- than dropped.
--
-- Nothing is estimated. A value absent from the source stays NULL, and every figure below was parsed
-- from the source string: hp from hp/bhp/cv/PS/kW, Nm from Nm/kgf.m/lb-ft, and litres from the litre
-- form only (the sheets print "22 Litres / 5.8 US gal", and the gallon figure must never win). The
-- sources disagree on decimal convention inside the same file ("7.1 kgf.m @ 13.500 RPM" beside
-- "103 Nm @ 9000 rpm"), so a separator is read from its own shape: exactly three trailing digits is
-- a thousands group, anything else is a decimal point. These sheets print both measurement systems
-- on most rows ("830.5 mm / 32.7 in", "790 mm (31.1 inches)"), so a measurement is read in mm
-- wherever mm was printed and converted from inches only where the metric figure beside it is
-- unreadable - 15 values came in that way.
--
-- Reading Nm before kgf.m is load-bearing rather than a preference. Many rows publish both, most of
-- them agreeing, and the Ninja ZX-10 does not: its pair reads "3.6 kgf-m / 103 Nm @ 9000 rpm", where
-- 103 Nm is 10.5 kgf.m, not 3.6.
-- The kgf figure is the source's own error, and taking the first unit printed would have stored a
-- third of the real torque. Where a row publishes power twice - "60 hp / 43.7 kW @ 9800 rpm (rear
-- tyre 54.2 hp @ 9500 rpm)" - the crank figure is the stored one, because that is the figure every
-- other brand in this catalogue publishes. The rear-wheel figure is not discarded: it goes to the
-- long tail as 'Potência na Roda Traseira', and the ram-air rating the ZX-11 and ZX-12 publish goes
-- there too, as 'Potência com Ram Air'. Kawasaki is the only brand here that quotes one.
--
-- One source figure is not taken on trust: the cylinder count. Bore, stroke and displacement are
-- printed on the same sheet, so their product decides the count whenever the prose beside them
-- disagrees (0 corrections here). In the prose, "V-Twin" is read as two cylinders, and the "Four"
-- in "Four stroke" is not read as a count - every sheet in this snapshot opens with those two words,
-- so a rule that took the first number word would have called the whole catalogue a four, singles
-- included.
--
-- 14 rows publish something in the compression-ratio cell that is not a ratio: motorcyclespecs
-- prints "76 x 58 mm" for the ZX-11, which is that engine's bore and stroke - the same 76 mm and
-- 58 mm the row's own bore and stroke fields already carry, so the mistake is provable from the row
-- itself. A value without the shape of a ratio is refused rather than stored, because
-- compression_ratio is a row of the comparison table and a dimension pair rendered there is worse
-- than a dash. The real ratio is put back by the errata table below, which is where that mistake
-- turns out to have come from.
--
-- final_drive gets the same treatment for the same reason (1 row refused). A final drive is a
-- chain, a shaft or a belt, and the KX 250 F publishes "Chassis" under it - the scraper's extraction
-- has run on into the next heading of the source table. Every other value in the snapshot names a
-- real drive type, so requiring one costs nothing and keeps a table heading from being served as a
-- drivetrain fact. That row gets its chain back from the errata table below.
--
-- Two kinds of extraction damage are repaired, and each is repaired only to something the source
-- itself makes unambiguous. A space in front of a decimal point is rejoined (10 values): the Vulcan
-- Nomad publishes its dry weight as "337 .0 kg / 739 lbs", and ".0" is not a number a split could
-- have produced, so 337.0 is the only reading. That repair is worth more than it looks - left alone,
-- the unit-anchored read walks past the stranded "337" and takes "0 kg", which the weight bound then
-- drops, so the row loses a figure it published perfectly clearly. The second is a unit label: 5 rows
-- give consumption as "15.3 lm/lit", where there is no such unit, the denominator is intact, and the
-- figure sits among the "15.2 km/lit" and "16.5 km/lit" its siblings carry, so the damaged "k" is
-- restored and nothing else (5 values).
--
-- Two other damaged values are not rescued by any parsing rule, because doing so would mean deriving
-- a figure rather than reading one. The KLX 650 publishes its stroke as "S3mm" on 3 rows - a letter
-- where a digit belongs, and a fault upstream rather than in this scrape, since moto-data.net still
-- prints that same string today. Its bore (100 mm) and displacement (651 cc) do imply an 83 mm
-- stroke, but a figure computed from two others is not one the manufacturer published, so the bound
-- drops the "3mm" fragment and the errata table below supplies the published 83 mm instead - the
-- arithmetic only corroborates it. The row reading "34.5 mp/g" is left alone for a different reason:
-- the unit it was meant to be is mpg, ambiguous between the UK and US gallon, and so refused even when
-- spelled correctly. Spaced-out integers are refused rather than read as their first fragment -
-- 1 numeric read was refused on that rule. Every one of them is the same consumption
-- field, reading "1 9.3 km/lit", and it is worth saying why that refusal is not merely tidy. The
-- digit guard cannot catch this one on its own: in "1 9.3" the trailing "3" is preceded by "9.",
-- not by a digit and a space, so the read comes back as 3 km/l. Here that works out to 33 l/100km
-- and the plausibility bound rejects it anyway - but "1 2.5 km/lit" would read 5 km/l and store
-- 20 l/100km, which is wrong and sits comfortably inside the range no bound would question. The
-- whole string is refused instead, which is the only check that holds whatever the fragments are,
-- and the errata table below restores that one row from the rejoined 19.3 km/lit.
--
-- Gear counts are read from four spellings, because these sheets use all of them: "6 Speed",
-- "6-speed", "5-speed, return" and "Five-speed with wet multi-disc manual clutch". A digits-only
-- rule silently misses every row written the spelled-out way.
--
-- A short errata table is the one exception to "everything here came from the snapshot", and it is
-- listed in full so it can be audited. 19 values across 4 rules are supplied by tools/
-- import-kawasaki-specs.mjs itself rather than by kawasaki_motos.json, each one published by a named
-- source cited beside it in that file, and each applied ONLY where the parsed value is already NULL -
-- so a figure the snapshot did publish can never be overwritten by one of these:
--   compression_ratio 14
--   final_drive 1
--   fuel_consumption_l_100km 1
--   stroke_mm 3
-- The largest of them is the ZZ-R1100/ZX-11 compression ratio, and it is really a transposition being
-- undone rather than a figure being imported. The source sheet prints, verbatim, "Bore x Stroke:
-- 11.0:1" and "Compression Ratio: 76 x 58 mm" - the two labels are swapped. The snapshot inherited
-- only half of that swap, because the scraper took bore and stroke from a sheet that labels them
-- correctly (hence the 76 mm and 58 mm on these rows) and took compression from the sheet with the
-- swap. So 11.0:1 was published on the row's own sheet and lost in transit; the 2000-01 sheet carries
-- the same figure under the correct label, which is what confirms it.
--
-- Implausible figures are dropped rather than stored, each against the range its column can sensibly
-- hold:
--   dry_weight_above_kerb 4, stroke_mm 3
-- The 3 strokes dropped are the KLX 650's "S3mm", described above: the bound is what catches
-- a letter-for-digit fault, because the fragment it leaves behind is a number in its own right.
-- The 4 dry weights dropped for exceeding kerb weight are rows where the two sheets disagree:
-- the dry figure comes from the global sheet and the kerb figure from the Brazilian one, and they
-- are not always describing the same model-year. Dropping the dry figure keeps the row rather than
-- losing the whole import to the CHECK that would otherwise abort it.
-- 29 values exceeded their column width and were cut at a word boundary rather than mid-word.
--
-- emission_standard is NULL on every row, and that is the source position rather than a gap in the
-- parsing: no sheet in this snapshot names a Euro or Proconve level anywhere, under any exhaust or
-- catalytic-converter heading. Nothing is inferred from the model year - compliance is a published
-- fact, and a standard derived from a date would be indistinguishable from a real one once stored.
--
-- Caveat worth knowing before trusting any single row. Almost none of these model-years is in
-- current production, so motorcyclist.com.br reaches only a handful of them and the rest lean on
-- motorcyclespecs.co.za and totalmotorcycle.com, which publish the global sheet rather than the
-- Brazilian one and reuse a single sheet across a model's whole production run. Figures are
-- representative of the model, not specific to the year on the row. The scraper grades its own
-- matches, and not all 200 are exact: 178 matched a sheet outright, 16 matched a neighbouring
-- generation, and 6 matched nothing at all. The last grade is the one to distrust spec by spec.
--
-- Images. The scraper stores its gallery under img/kawasaki/<model>/, which is per model rather than
-- per model-year, so the 126 distinct photos below cover 190 of the 194 rows. Each row still gets its own
-- stored copy under a name derived from its slug (UUID v5, matching the shape FileStorageServiceImpl
-- will read): MotorcycleService treats the file as owned by the row and deletes it when the
-- motorcycle or its image is deleted, so a shared file name would blank every other row pointing at
-- it.
-- The remaining 4 rows had no photo published by any source:
--   kawasaki-kx-250-250-f-2006, kawasaki-kx-450-f-2006, kawasaki-kx-250-250-f-2007,
--   kawasaki-kx-450-f-2007.
-- The files themselves are NOT in the repository - uploads/ is gitignored. Run
-- `node tools/import-kawasaki-specs.mjs` to materialise them from a zontes-scraper checkout; until
-- then these rows serve a 404 for their image.
--
-- Existing rows are only ever gap-filled: every write is COALESCE(existing, imported), so an admin
-- edit, an uploaded image or a richer earlier import is never overwritten. That matters for exactly
-- four rows here - the hand-curated Ninja ZX-6R 2024, Z900 2024, Z900 2026 and Versys 1000 SE 2024 in
-- R__dev_seed.sql - because the other 196 arrived from FIPE with every specification column NULL, so
-- for them a gap-fill is a full population. Long-tail specs use ON CONFLICT DO NOTHING, which leaves
-- the FIPE seed's own 'Fuel' and 'Reference price (BRL)' intact, and reuse the key names the Honda,
-- Yamaha, Royal Enfield, Harley-Davidson and BMW imports chose so a cross-brand comparison lines its
-- rows up. Category is deliberately not touched on existing rows. Repeatable and idempotent:
-- re-running changes nothing once it has been applied.
--
-- One consequence of that rule is worth stating outright, because it is invisible from this file
-- alone. displacement_cc is the only engine column the FIPE seed already fills, and it fills it by
-- parsing the cc out of the model descriptor - so "NINJA ZX-11 1100cc" arrives holding 1100 for an
-- engine the manufacturer builds at 1052 cc. Gap-fill means the FIPE figure wins wherever it has
-- one: of the 194 displacements this import carries, 79 land on rows FIPE left empty, 7 agree with
-- what FIPE already stored, and 108 are refused in favour of it - 102 of those because FIPE holds the
-- rounder marketing number the model is named after. Nothing here is wrong, and no figure is lost
-- that was ever published: the scraped value is simply not the one on display for those rows.
-- Changing that would mean letting this file overwrite a column rather than fill it, which is a
-- different policy from the one every brand import in this catalogue follows, and not one to adopt
-- brand by brand.
--
-- Populated column counts across the 194 imported rows:
--   engine: displacement_cc 194, max_power_hp 170, max_torque_nm 169, gears 194, cylinders 194
--   frame:  frame_type 132, front_suspension 187, front_tyre 185, abs_type 2
--   dims:   kerb_weight_kg 121, dry_weight_kg 161, seat_height_mm 174, fuel_capacity_l 184 (187 rows get a dimension block)
--   other:  top_speed_kph 124, fuel_consumption_l_100km 93, emission_standard 0, final_drive 191
--   image_url 190; long-tail spec rows: 1561
-- Rows carrying nothing usable and therefore not emitted:
--   kawasaki-avajet-100cc-classic-100cc-1997, kawasaki-maxi-ii-100cc-1997,
--   kawasaki-maxi-ii-100cc-1998, kawasaki-maxi-ii-100cc-1999, kawasaki-kz-1000-touring-2001,
--   kawasaki-kz-1000-touring-2002.

BEGIN;

CREATE TEMP TABLE tmp_kawasaki_spec_import (
    row_no                   bigint PRIMARY KEY,
    slug                     varchar(160) NOT NULL,
    is_new                   boolean NOT NULL,
    brand                    varchar(60),
    model                    varchar(120),
    model_year               integer,
    category                 varchar(20),
    image_url                varchar(512),
    frame_type               varchar(120),
    front_suspension         varchar(160),
    rear_suspension          varchar(160),
    front_brake              varchar(160),
    rear_brake               varchar(160),
    abs_type                 varchar(80),
    front_tyre               varchar(60),
    rear_tyre                varchar(60),
    engine_type              varchar(80),
    displacement_cc          integer,
    cylinders                integer,
    valves_per_cylinder      integer,
    max_power_hp             numeric(6,1),
    max_power_rpm            integer,
    max_torque_nm            numeric(6,1),
    max_torque_rpm           integer,
    compression_ratio        varchar(20),
    bore_mm                  numeric(6,2),
    stroke_mm                numeric(6,2),
    cooling_system           varchar(40),
    fuel_system              varchar(120),
    transmission_type        varchar(60),
    gears                    integer,
    final_drive              varchar(40),
    top_speed_kph            integer,
    fuel_consumption_l_100km numeric(5,2),
    emission_standard        varchar(30),
    length_mm                integer,
    width_mm                 integer,
    height_mm                integer,
    wheelbase_mm             integer,
    seat_height_mm           integer,
    ground_clearance_mm      integer,
    kerb_weight_kg           numeric(6,1),
    dry_weight_kg            numeric(6,1),
    fuel_capacity_l          numeric(5,1),
    motorcycle_id            bigint,
    engine_id                bigint,
    dimension_id             bigint
) ON COMMIT DROP;

CREATE TEMP TABLE tmp_kawasaki_spec_kv (
    row_no     bigint NOT NULL,
    spec_key   varchar(80) NOT NULL,
    spec_value varchar(500),
    PRIMARY KEY (row_no, spec_key)
) ON COMMIT DROP;






-- Bind every imported row to its catalogue row. The FIPE seed derives the same slug from the same
-- FIPE model descriptor, so this is an equality join and not a fuzzy match.
UPDATE tmp_kawasaki_spec_import s
SET motorcycle_id = m.id,
    engine_id     = m.engine_specification_id,
    dimension_id  = m.dimension_id
FROM motorcycles m
WHERE m.slug = s.slug;

-- What counts as new is decided here, from the database, not from the flag carried in the VALUES
-- above. That flag records what was true when this file was generated; the catalogue may since have
-- gained or lost the model. Deriving it means an existing model is never inserted twice, and a model
-- the catalogue does not have is created rather than quietly dropped.
UPDATE tmp_kawasaki_spec_import SET is_new = (motorcycle_id IS NULL);

DO $$
BEGIN
    IF pg_get_serial_sequence('engine_specifications', 'id') IS NULL
       OR pg_get_serial_sequence('dimensions', 'id') IS NULL
       OR pg_get_serial_sequence('motorcycles', 'id') IS NULL THEN
        RAISE EXCEPTION 'A target table has no serial/identity sequence';
    END IF;
END $$;

-- ---------------------------------------------------------------------------
-- New models: allocate ids, then build engine, dimension and catalogue rows.
-- ---------------------------------------------------------------------------
UPDATE tmp_kawasaki_spec_import
SET motorcycle_id = nextval(pg_get_serial_sequence('motorcycles', 'id')::regclass),
    engine_id     = nextval(pg_get_serial_sequence('engine_specifications', 'id')::regclass)
WHERE is_new;

-- A dimension row is created only where the source published a measurement; an empty placeholder
-- would add a row that exists only to render dashes in the comparison table.
UPDATE tmp_kawasaki_spec_import
SET dimension_id = nextval(pg_get_serial_sequence('dimensions', 'id')::regclass)
WHERE is_new
  AND num_nonnulls(length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm,
                   ground_clearance_mm, kerb_weight_kg, dry_weight_kg, fuel_capacity_l) > 0;

    id, engine_type, displacement_cc, cylinders, valves_per_cylinder, max_power_hp, max_power_rpm,
    max_torque_nm, max_torque_rpm, compression_ratio, bore_mm, stroke_mm, cooling_system, fuel_system,
    transmission_type, gears, final_drive, top_speed_kph, fuel_consumption_l_100km, emission_standard
)
SELECT engine_id, engine_type, displacement_cc, cylinders, valves_per_cylinder, max_power_hp, max_power_rpm,
       max_torque_nm, max_torque_rpm, compression_ratio, bore_mm, stroke_mm, cooling_system, fuel_system,
       transmission_type, gears, final_drive, top_speed_kph, fuel_consumption_l_100km, emission_standard
FROM tmp_kawasaki_spec_import
WHERE is_new
ORDER BY row_no;

    id, length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm, ground_clearance_mm,
    kerb_weight_kg, dry_weight_kg, fuel_capacity_l
)
SELECT dimension_id, length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm, ground_clearance_mm,
       kerb_weight_kg, dry_weight_kg, fuel_capacity_l
FROM tmp_kawasaki_spec_import
WHERE is_new AND dimension_id IS NOT NULL
ORDER BY row_no;

-- price_eur stays NULL: a model outside the FIPE snapshot has no reference price here, and a guessed
-- one would be indistinguishable from a real one once it is in the catalogue.
    id, slug, version, brand, model, model_year, category, price_eur, image_url, description,
    frame_type, front_suspension, rear_suspension, front_brake, rear_brake, abs_type,
    front_tyre, rear_tyre, engine_specification_id, dimension_id, created_at, updated_at
)
SELECT motorcycle_id, slug, 0, brand, model, model_year, category, NULL, image_url, NULL,
       frame_type, front_suspension, rear_suspension, front_brake, rear_brake, abs_type,
       front_tyre, rear_tyre, engine_id, dimension_id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM tmp_kawasaki_spec_import
WHERE is_new
ORDER BY row_no;

-- ---------------------------------------------------------------------------
-- Existing models: gap-fill only.
-- ---------------------------------------------------------------------------

-- The FIPE seed created an engine block for every row it inserted, but an earlier import may not
-- have. Give those an engine row first, so their figures are not silently dropped below.
UPDATE tmp_kawasaki_spec_import
SET engine_id = nextval(pg_get_serial_sequence('engine_specifications', 'id')::regclass)
WHERE NOT is_new AND engine_id IS NULL;

SELECT s.engine_id
FROM tmp_kawasaki_spec_import s
WHERE NOT s.is_new
  AND s.engine_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM engine_specifications e WHERE e.id = s.engine_id)
ORDER BY s.row_no;

UPDATE motorcycles m
SET engine_specification_id = s.engine_id
FROM tmp_kawasaki_spec_import s
WHERE m.id = s.motorcycle_id AND NOT s.is_new AND m.engine_specification_id IS NULL;

UPDATE engine_specifications e
SET engine_type              = COALESCE(e.engine_type, s.engine_type),
    displacement_cc          = COALESCE(e.displacement_cc, s.displacement_cc),
    cylinders                = COALESCE(e.cylinders, s.cylinders),
    valves_per_cylinder      = COALESCE(e.valves_per_cylinder, s.valves_per_cylinder),
    max_power_hp             = COALESCE(e.max_power_hp, s.max_power_hp),
    max_power_rpm            = COALESCE(e.max_power_rpm, s.max_power_rpm),
    max_torque_nm            = COALESCE(e.max_torque_nm, s.max_torque_nm),
    max_torque_rpm           = COALESCE(e.max_torque_rpm, s.max_torque_rpm),
    compression_ratio        = COALESCE(e.compression_ratio, s.compression_ratio),
    bore_mm                  = COALESCE(e.bore_mm, s.bore_mm),
    stroke_mm                = COALESCE(e.stroke_mm, s.stroke_mm),
    cooling_system           = COALESCE(e.cooling_system, s.cooling_system),
    fuel_system              = COALESCE(e.fuel_system, s.fuel_system),
    transmission_type        = COALESCE(e.transmission_type, s.transmission_type),
    gears                    = COALESCE(e.gears, s.gears),
    final_drive              = COALESCE(e.final_drive, s.final_drive),
    top_speed_kph            = COALESCE(e.top_speed_kph, s.top_speed_kph),
    fuel_consumption_l_100km = COALESCE(e.fuel_consumption_l_100km, s.fuel_consumption_l_100km),
    emission_standard        = COALESCE(e.emission_standard, s.emission_standard)
FROM tmp_kawasaki_spec_import s
WHERE e.id = s.engine_id AND NOT s.is_new;

-- A row seeded from FIPE carries no dimension block at all, so allocate one wherever this import
-- has something to put in it.
UPDATE tmp_kawasaki_spec_import
SET dimension_id = nextval(pg_get_serial_sequence('dimensions', 'id')::regclass)
WHERE NOT is_new
  AND dimension_id IS NULL
  AND num_nonnulls(length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm,
                   ground_clearance_mm, kerb_weight_kg, dry_weight_kg, fuel_capacity_l) > 0;

    id, length_mm, width_mm, height_mm, wheelbase_mm, seat_height_mm, ground_clearance_mm,
    kerb_weight_kg, dry_weight_kg, fuel_capacity_l
)
SELECT s.dimension_id, s.length_mm, s.width_mm, s.height_mm, s.wheelbase_mm, s.seat_height_mm,
       s.ground_clearance_mm, s.kerb_weight_kg, s.dry_weight_kg, s.fuel_capacity_l
FROM tmp_kawasaki_spec_import s
WHERE NOT s.is_new
  AND s.dimension_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM dimensions d WHERE d.id = s.dimension_id)
ORDER BY s.row_no;

-- Where a dimension block already existed, gap-fill it the same way as the engine block.
UPDATE dimensions d
SET length_mm           = COALESCE(d.length_mm, s.length_mm),
    width_mm            = COALESCE(d.width_mm, s.width_mm),
    height_mm           = COALESCE(d.height_mm, s.height_mm),
    wheelbase_mm        = COALESCE(d.wheelbase_mm, s.wheelbase_mm),
    seat_height_mm      = COALESCE(d.seat_height_mm, s.seat_height_mm),
    ground_clearance_mm = COALESCE(d.ground_clearance_mm, s.ground_clearance_mm),
    kerb_weight_kg      = COALESCE(d.kerb_weight_kg, s.kerb_weight_kg),
    dry_weight_kg       = COALESCE(d.dry_weight_kg, s.dry_weight_kg),
    fuel_capacity_l     = COALESCE(d.fuel_capacity_l, s.fuel_capacity_l)
FROM tmp_kawasaki_spec_import s
WHERE d.id = s.dimension_id AND NOT s.is_new;

-- A gap-fill that would push dry weight above a kerb weight already on the row is dropped: the
-- CHECK would otherwise abort the entire import over one bad source figure.
UPDATE dimensions
SET dry_weight_kg = NULL
WHERE dry_weight_kg IS NOT NULL
  AND kerb_weight_kg IS NOT NULL
  AND dry_weight_kg > kerb_weight_kg;

-- image_url is gap-filled like everything else, so an image an admin uploaded through
-- POST /api/v1/motorcycles/{id}/image always wins over the scraped one. It is never cleared here:
-- removeImage deletes the file behind a URL this API issued, and this import must not orphan one.
UPDATE motorcycles m
SET frame_type       = COALESCE(m.frame_type, s.frame_type),
    front_suspension = COALESCE(m.front_suspension, s.front_suspension),
    rear_suspension  = COALESCE(m.rear_suspension, s.rear_suspension),
    front_brake      = COALESCE(m.front_brake, s.front_brake),
    rear_brake       = COALESCE(m.rear_brake, s.rear_brake),
    abs_type         = COALESCE(m.abs_type, s.abs_type),
    front_tyre       = COALESCE(m.front_tyre, s.front_tyre),
    rear_tyre        = COALESCE(m.rear_tyre, s.rear_tyre),
    image_url        = COALESCE(m.image_url, s.image_url),
    dimension_id     = COALESCE(m.dimension_id, s.dimension_id),
    -- @Version belongs to Hibernate; bump it here because this writes behind the ORM's back, so a
    -- session holding a stale copy of one of these rows fails its next flush instead of quietly
    -- overwriting the import.
    version          = m.version + 1,
    updated_at       = CURRENT_TIMESTAMP
FROM tmp_kawasaki_spec_import s
WHERE m.id = s.motorcycle_id
  AND NOT s.is_new
  -- Each arm is "the row lacks it AND the import supplies it", so a row this file has nothing left
  -- to add is not touched at all. Testing only for NULL would bump version and updated_at on every
  -- re-run for any column the source never published.
  AND ((m.frame_type IS NULL AND s.frame_type IS NOT NULL)
       OR (m.front_suspension IS NULL AND s.front_suspension IS NOT NULL)
       OR (m.rear_suspension IS NULL AND s.rear_suspension IS NOT NULL)
       OR (m.front_brake IS NULL AND s.front_brake IS NOT NULL)
       OR (m.rear_brake IS NULL AND s.rear_brake IS NOT NULL)
       OR (m.abs_type IS NULL AND s.abs_type IS NOT NULL)
       OR (m.front_tyre IS NULL AND s.front_tyre IS NOT NULL)
       OR (m.rear_tyre IS NULL AND s.rear_tyre IS NOT NULL)
       OR (m.image_url IS NULL AND s.image_url IS NOT NULL)
       OR (m.dimension_id IS NULL AND s.dimension_id IS NOT NULL));

-- ---------------------------------------------------------------------------
-- Long-tail specs. DO NOTHING preserves whatever is already stored under the same key,
-- including the FIPE seed's own 'Fuel' and 'Reference price (BRL)'.
-- ---------------------------------------------------------------------------
SELECT s.motorcycle_id, k.spec_key, k.spec_value
FROM tmp_kawasaki_spec_kv k
JOIN tmp_kawasaki_spec_import s ON s.row_no = k.row_no
WHERE s.motorcycle_id IS NOT NULL
  AND k.spec_value IS NOT NULL
  AND btrim(k.spec_value) <> ''
ON CONFLICT (motorcycle_id, spec_key) DO NOTHING;

-- ---------------------------------------------------------------------------
-- Defensive checks before commit.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
    bad bigint;
BEGIN
    SELECT count(*) INTO bad
    FROM tmp_kawasaki_spec_import s
    LEFT JOIN motorcycles m ON m.id = s.motorcycle_id
    WHERE m.id IS NULL;
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Kawasaki spec import: % rows did not resolve to a catalogue row', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM tmp_kawasaki_spec_import s
    JOIN motorcycles m ON m.id = s.motorcycle_id
    WHERE s.engine_id IS NOT NULL AND m.engine_specification_id IS DISTINCT FROM s.engine_id;
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Kawasaki spec import: % rows have a mismatched engine block', bad;
    END IF;

    SELECT count(*) INTO bad
    FROM dimensions
    WHERE dry_weight_kg IS NOT NULL AND kerb_weight_kg IS NOT NULL AND dry_weight_kg > kerb_weight_kg;
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Kawasaki spec import: % dimension rows have dry weight above kerb weight', bad;
    END IF;

    -- lower(brand) rather than brand: V4 normalised casing before either seed had inserted a row, so
    -- an equality test here would silently depend on which seed wrote the row.
    SELECT count(*) INTO bad
    FROM motorcycles
    WHERE lower(brand) = 'kawasaki' AND slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$';
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Kawasaki spec import: % rows have a slug the public routing cannot use', bad;
    END IF;

    -- Every stored image URL has to be a name ImageController can actually serve: FileStorageServiceImpl
    -- reads UUID + jpg/png/webp and nothing else, so a name outside that shape is a silent 404.
    SELECT count(*) INTO bad
    FROM tmp_kawasaki_spec_import
    WHERE image_url IS NOT NULL
      AND image_url !~ '^/api/v1/images/motorcycles/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$';
    IF bad <> 0 THEN
        RAISE EXCEPTION 'Kawasaki spec import: % image URLs are not a name the image endpoint can serve', bad;
    END IF;
END $$;

COMMIT;
